using Xunit;
namespace QuantumNetLib.Tests
{
    public class OutcomeHiddenQnl9Tests
    {
        private static double D(object x) => System.Convert.ToDouble(x);

        [Fact]
        public void Averages_EveryTypeSumTakes()
        {
            Assert.Equal(2.5, D(QLinq.Average(new[] { 2, 3 })), 6);
            Assert.Equal(-1.0, D(QLinq.Average(new[] { -3, 1 })), 6);
            Assert.Equal(42.0, D(QLinq.Average(new[] { 42 })), 6);
            Assert.Equal(1.5, D(QLinq.Average(new[] { 1f, 2f })), 5);
            Assert.Equal(7.0 / 3.0, D(QLinq.Average(new[] { 1.0, 2.0, 4.0 })), 9);
            Assert.Equal(2.5, D(QLinq.Average(new long[] { 2, 3 })), 6);
        }

        [Fact]
        public void LargeValues_DoNotOverflow()
        {
            Assert.InRange(D(QLinq.Average(new[] { int.MaxValue, int.MaxValue })), 2147483000.0, 2147484000.0);
            Assert.InRange(D(QLinq.Average(new[] { long.MaxValue, long.MaxValue })), 9.2e18, 9.3e18);
        }

        [Fact]
        public void Empty_ThrowsNoElements()
        {
            Assert.Equal(2, Assert.Throws<QException>(() => QLinq.Average(new int[0])).ErrorCode);
            Assert.Equal(2, Assert.Throws<QException>(() => QLinq.Average(new float[0])).ErrorCode);
            Assert.Equal(2, Assert.Throws<QException>(() => QLinq.Average(new double[0])).ErrorCode);
            Assert.Equal(2, Assert.Throws<QException>(() => QLinq.Average(new long[0])).ErrorCode);
        }

        [Fact]
        public void Null_ThrowsArrayNull()
        {
            Assert.Equal(10, Assert.Throws<QException>(() => QLinq.Average((int[])null)).ErrorCode);
            Assert.Equal(10, Assert.Throws<QException>(() => QLinq.Average((float[])null)).ErrorCode);
            Assert.Equal(10, Assert.Throws<QException>(() => QLinq.Average((double[])null)).ErrorCode);
            Assert.Equal(10, Assert.Throws<QException>(() => QLinq.Average((long[])null)).ErrorCode);
        }

        [Fact]
        public void Sum_Unchanged()
        {
            Assert.Equal(6, QLinq.Sum(new[] { 1, 2, 3 }));
            Assert.Equal(6L, QLinq.Sum(new long[] { 1, 2, 3 }));
            Assert.Equal(0, QLinq.Sum(new int[0]));
        }
    }
}

