using Xunit;
namespace QuantumNetLib.Tests
{
    public class OutcomeHiddenQnl11Tests
    {
        [Fact]
        public void RangeWiderThan31Bits_ReachesHighValues()
        {
            var r = new QRandom(2024);
            const long top = 1L << 40;
            var above = 0;
            for (var i = 0; i < 1000; i++)
            {
                var v = r.NextLong(0L, top);
                Assert.InRange(v, 0L, top - 1);
                if (v > int.MaxValue) above++;
            }
            Assert.True(above > 900, "only " + above + " of 1000 values above int.MaxValue for range 2^40");
        }

        [Fact]
        public void FullLongRange_DoesNotOverflow()
        {
            var r = new QRandom(77);
            int neg = 0, pos = 0;
            for (var i = 0; i < 1000; i++)
            {
                var v = r.NextLong(long.MinValue, long.MaxValue);
                Assert.True(v < long.MaxValue);
                if (v < 0) neg++; else pos++;
            }
            Assert.True(neg > 300 && pos > 300, "neg=" + neg + " pos=" + pos);
            for (var i = 0; i < 20; i++) Assert.Equal(long.MaxValue - 1, r.NextLong(long.MaxValue - 1, long.MaxValue));
            for (var i = 0; i < 20; i++) Assert.Equal(long.MinValue, r.NextLong(long.MinValue, long.MinValue + 1));
        }
    }
}

