using Microsoft.VisualStudio.TestTools.UnitTesting;
using LibraryManagementSystem.Data;
using LibraryManagementSystem.Models;
using System;
using System.Collections.Generic;
using System.Data;
using System.Linq;
using System.Reflection;
using System.Runtime.CompilerServices;

namespace LibraryManagementSystemTests.ModelTests
{
    [TestClass]
    public class OutcomeHiddenLms14ReadTests
    {
        private static DataTable Table(params string[] eventTypes)
        {
            var t = new DataTable();
            t.Columns.Add("id", typeof(int));
            t.Columns.Add("user_id", typeof(int));
            t.Columns.Add("event_type", typeof(string));
            t.Columns.Add("event_details", typeof(string));
            t.Columns.Add("ip_address", typeof(string));
            t.Columns.Add("user_agent", typeof(string));
            t.Columns.Add("created_at", typeof(DateTime));
            t.Columns.Add("username", typeof(string));
            t.Columns.Add("first_name", typeof(string));
            t.Columns.Add("last_name", typeof(string));
            var id = 1;
            foreach (var e in eventTypes)
                t.Rows.Add(id++, 1, e, "details", "127.0.0.1", "agent", DateTime.Now, "user", "First", "Last");
            return t;
        }

        // Maps rows through the repository's own DataRow/DataTable -> AuditLog mapping, whatever it is named.
        private static List<AuditLog> Map(DataTable table)
        {
            var repoType = typeof(AuditLogRepository);
            var repo = RuntimeHelpers.GetUninitializedObject(repoType);
            const BindingFlags all = BindingFlags.Instance | BindingFlags.Static | BindingFlags.Public | BindingFlags.NonPublic;
            var methods = repoType.GetMethods(all);

            var rowMapper = methods.FirstOrDefault(m =>
                m.ReturnType == typeof(AuditLog) &&
                m.GetParameters().Length == 1 &&
                m.GetParameters()[0].ParameterType == typeof(DataRow));
            if (rowMapper != null)
                return table.Rows.Cast<DataRow>()
                    .Select(r => (AuditLog)rowMapper.Invoke(rowMapper.IsStatic ? null : repo, new object[] { r })!)
                    .ToList();

            var tableMapper = methods.FirstOrDefault(m =>
                typeof(IEnumerable<AuditLog>).IsAssignableFrom(m.ReturnType) &&
                m.GetParameters().Length == 1 &&
                m.GetParameters()[0].ParameterType == typeof(DataTable));
            Assert.IsNotNull(tableMapper, "AuditLogRepository has no DataRow/DataTable -> AuditLog mapping");
            return ((IEnumerable<AuditLog>)tableMapper.Invoke(tableMapper.IsStatic ? null : repo, new object[] { table })!).ToList();
        }

        [TestMethod]
        public void StoredSnakeCaseEventTypes_MapBackToTheirEnumValues()
        {
            var logs = Map(Table("FAILED_LOGIN", "PASSWORD_CHANGE", "SESSION_EXPIRED", "LOGIN", "LOGOUT", "REGISTRATION"));
            CollectionAssert.AreEqual(
                new[]
                {
                    AuditEventType.FailedLogin, AuditEventType.PasswordChange, AuditEventType.SessionExpired,
                    AuditEventType.Login, AuditEventType.Logout, AuditEventType.Registration
                },
                logs.Select(l => l.EventType).ToArray());
        }
    }
}

import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import net from 'node:net';
import { spawn } from 'node:child_process';
import sharp from 'sharp';
import { chromium } from 'playwright';

Object.assign(process.env, { ENV_FILE: '/nonexistent', IG_USER_ID: '1', IG_ACCESS_TOKEN: 't' });
const { sanitiseImage, UploadError } = await import('../server/uploads.js');

const ROOT = path.resolve(import.meta.dirname, '..');
const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'kv-hidden10-'));
const gifBuf = await sharp({ create: { width: 40, height: 30, channels: 3, background: '#c03' } }).gif().toBuffer();
const pngBuf = await sharp({ create: { width: 40, height: 30, channels: 3, background: '#03c' } }).png().toBuffer();

const freePort = () => new Promise((resolve, reject) => {
  const s = net.createServer();
  s.on('error', reject);
  s.listen(0, '127.0.0.1', () => { const { port } = s.address(); s.close(() => resolve(port)); });
});

// The real server in host mode on free ports; `node` stands in for omp.
async function startServer() {
  const [port, proxyPort] = [await freePort(), await freePort()];
  const child = spawn(process.execPath, ['server/index.js'], {
    cwd: ROOT,
    env: {
      ...process.env, ENV_FILE: '/nonexistent', JOB_RUNNER: 'host', HOST: '127.0.0.1', PORT: String(port),
      KEYPROXY_PORT: String(proxyPort), JOB_GATEWAY: '127.0.0.1', DATA_DIR: path.join(tmp, 'data'), ACCESS_CODE: 'test-code-123',
      MODEL_PROVIDER: 'anthropic', MODEL: 'anthropic/claude-opus-5-5', CLAUDE_OAUTH_TOKEN: 'sk-ant-oat01-test',
      MODEL_UPSTREAM_URL: 'http://127.0.0.1:9', JOB_OMP_BIN: process.execPath, IG_USER_ID: '', IG_ACCESS_TOKEN: '', RATE_LIMIT_PER_HOUR: '0',
    },
    stdio: ['ignore', 'pipe', 'pipe'],
    windowsHide: true,
  });
  let log = '';
  await new Promise((resolve, reject) => {
    const timer = setTimeout(() => reject(new Error(`server did not start:\n${log}`)), 60_000);
    const onData = (d) => { log += d; if (log.includes('[boot] listening')) { clearTimeout(timer); resolve(); } };
    child.stdout.on('data', onData);
    child.stderr.on('data', onData);
    child.once('exit', (code) => { clearTimeout(timer); reject(new Error(`server exited ${code}:\n${log}`)); });
  });
  return { base: `http://127.0.0.1:${port}`, stop: () => child.kill() };
}

let server;
let browser;
test.before(async () => {
  server = await startServer();
  browser = await chromium.launch();
});
test.after(async () => {
  await browser?.close();
  server?.stop();
  await new Promise((r) => setTimeout(r, 300));
  fs.rmSync(tmp, { recursive: true, force: true, maxRetries: 3 });
});

test('the server refuses GIF uploads as not_image and still takes JPEG, PNG and WebP', async () => {
  const gif = path.join(tmp, 'anim.gif');
  fs.writeFileSync(gif, gifBuf);
  await assert.rejects(sanitiseImage(gif, path.join(tmp, 'g')), (e) => e instanceof UploadError && e.code === 'not_image');
  for (const fmt of ['jpeg', 'png', 'webp']) {
    const f = path.join(tmp, `ok.${fmt}`);
    await sharp({ create: { width: 50, height: 40, channels: 3, background: '#123456' } }).toFormat(fmt).toFile(f);
    const out = await sanitiseImage(f, path.join(tmp, `out-${fmt}`));
    assert.deepEqual([out.width, out.height], [50, 40], fmt);
  }
  // also over HTTP: a GIF in an otherwise valid form is rejected
  const fd = new FormData();
  fd.append('clubName', 'Okan Sinema');
  fd.append('images', new Blob([gifBuf], { type: 'image/gif' }), 'logo.gif');
  const res = await fetch(`${server.base}/api/jobs`, { method: 'POST', headers: { 'X-Access-Code': 'test-code-123' }, body: fd });
  assert.equal(res.status, 400);
  assert.equal((await res.json()).error, 'not_image');
});

test('the file picker no longer offers GIF', () => {
  const html = fs.readFileSync(path.join(ROOT, 'public', 'index.html'), 'utf8');
  const tag = html.match(/<input[^>]*id="images"[^>]*>/)?.[0];
  assert.ok(tag, 'images input exists');
  const accept = tag.match(/accept="([^"]*)"/)?.[1] ?? '';
  assert.doesNotMatch(accept, /gif/i);
  for (const t of ['jpeg', 'png', 'webp']) assert.match(accept, new RegExp(t));
});

test('a picked or dropped GIF is refused in the browser before upload, other images still are added', async () => {
  const page = await browser.newPage();
  await page.goto(server.base, { waitUntil: 'networkidle' });
  await page.locator('#images').setInputFiles({ name: 'logo.gif', mimeType: 'image/gif', buffer: gifBuf });
  assert.equal(await page.locator('#thumbs li').count(), 0, 'picked gif is not added');
  assert.ok(await page.locator('#form-error').isVisible(), 'an error is shown for the picked gif');
  assert.notEqual((await page.locator('#form-error').innerText()).trim(), '');

  await page.locator('#images').setInputFiles({ name: 'logo.png', mimeType: 'image/png', buffer: pngBuf });
  assert.equal(await page.locator('#thumbs li').count(), 1, 'png is added');
  assert.ok(!(await page.locator('#form-error').isVisible()), 'no error for a png');

  // drag and drop goes past the accept attribute
  await page.evaluate((bytes) => {
    const dt = new DataTransfer();
    dt.items.add(new File([new Uint8Array(bytes)], 'dropped.gif', { type: 'image/gif' }));
    document.querySelector('.drop').dispatchEvent(new DragEvent('drop', { dataTransfer: dt, bubbles: true, cancelable: true }));
  }, [...gifBuf]);
  assert.equal(await page.locator('#thumbs li').count(), 1, 'dropped gif is not added');
  assert.ok(await page.locator('#form-error').isVisible(), 'an error is shown for the dropped gif');
  await page.close();
});

