const boot = async (name) => { const s = await startServer(name); servers.push(s); return s; };

// An empty club name: a request whose code is accepted ends in missing_name, a refused code in bad_code.
async function tryCode(base, code) {
  const fd = new FormData();
  fd.append('clubName', '');
  const res = await fetch(`${base}/api/jobs`, { method: 'POST', headers: { 'X-Access-Code': encodeURIComponent(code) }, body: fd });
  return { status: res.status, error: (await res.json().catch(() => ({}))).error };
}

test('the server accepts the access code with surrounding whitespace, and only that', async () => {
  const s = await boot('a');
  for (const code of [CODE, `  ${CODE} `, `\t${CODE}\u00A0`, `${CODE}\n`]) {
    assert.deepEqual(await tryCode(s.base, code), { status: 400, error: 'missing_name' }, JSON.stringify(code));
  }
  for (const code of ['test-code-124', 'TEST-CODE-123', ` ${CODE.slice(0, -1)} `]) {
    assert.deepEqual(await tryCode(s.base, code), { status: 403, error: 'bad_code' }, JSON.stringify(code));
  }
});

test('wrong codes still lock an IP out after ten tries', async () => {
  const s = await boot('b');
  for (let i = 0; i < 10; i++) assert.equal((await tryCode(s.base, ` wrong-${i} `)).status, 403);
  assert.deepEqual(await tryCode(s.base, CODE), { status: 429, error: 'rate_limited' });
});

