const fs=require('fs'),vm=require('vm');
function any(){
  const store={},f=function(){};
  return new Proxy(f,{
    get(t,k){
      if(k===Symbol.toPrimitive)return h=>h==='number'?0:'';
      if(k==='then')return undefined;
      if(k===Symbol.iterator)return function*(){};
      if(k==='length')return 0;
      if(k in t&&k!=='prototype'&&k!=='name')return t[k];
      return k in store?store[k]:(store[k]=any());
    },
    set(t,k,v){store[k]=v;return true},
    apply(){return any()},
    construct(){return any()},
  });
}
function game(lang){
  const files=[...fs.readFileSync('Loamrift.html','utf8').matchAll(/<script src="(js\/[^"?]+)/g)].map(m=>m[1]).filter(f=>f!=='js/main.js');
  const mem={'loamrift.lang':lang},els={},document=any();
  document.getElementById=id=>els[id]||(els[id]=any());
