    requestAnimationFrame:()=>0,cancelAnimationFrame(){},performance:{now:()=>0},
    localStorage:{getItem:k=>k in mem?mem[k]:null,setItem:(k,v)=>{mem[k]=String(v)},removeItem:k=>{delete mem[k]},key:()=>null,length:0},
    sessionStorage:{getItem:()=>null,setItem(){},removeItem(){}},indexedDB:{open(){throw new Error('no idb')}},
    document,navigator:{userAgent:'node',language:'en',getGamepads:()=>[],maxTouchPoints:0},location:{search:'',hash:'',href:'',reload(){}},
    addEventListener(){},removeEventListener(){},matchMedia:()=>({matches:false,addEventListener(){}}),
