    URL,URLSearchParams,TextEncoder,TextDecoder,Blob:function(){},FileReader:function(){},innerWidth:1280,innerHeight:720,devicePixelRatio:1,
    fetch:()=>new Promise(()=>{}),confirm:()=>true,alert(){},prompt:()=>null};
