import assert from 'node:assert/strict';
import test from 'node:test';
import {mkdtemp, mkdir, rm, writeFile} from 'node:fs/promises';
import path from 'node:path';
import {validateToolArguments} from '@earendil-works/pi-ai';
import {createLearnings} from '../extensions/apex-features/learnings.mjs';

async function fixture(t) { const cwd = await mkdtemp(path.join(process.cwd(), 'tests/.learnings-fixture-')); t.after(() => rm(cwd, {recursive: true, force: true})); return cwd; }
const facts = text => (text.match(/^- /gm) ?? []).length;

test('remember stores facts up to 2000 UTF-8 bytes and refuses longer ones', async t => {
  const cwd = await fixture(t); const store = createLearnings({cwd});
  const long = 'b'.repeat(1990) + ' ok-2000';
  assert.equal(Buffer.byteLength(long), 1998);
  assert.equal((await store.append(long)).ok, true, 'a 1998-byte fact must be stored');
  const exact = 'c'.repeat(2000);
  const stored = await store.append(exact);
  assert.equal(stored.ok, true, stored.reason);
  assert.equal((await store.append('é'.repeat(1000))).ok, true, '2000 bytes of two-byte characters fit');
  assert.equal((await store.append('d'.repeat(2001))).ok, false, '2001 bytes must be refused');
  assert.equal((await store.append('é'.repeat(1001))).ok, false, 'the cap keeps counting UTF-8 bytes (2002 here)');
  const loaded = await store.load();
  assert.equal(loaded.ok, true); assert.equal(facts(loaded.content), 3); assert.ok(loaded.content.includes(exact));
});

test('Pi accepts a 2000-character fact for the remember tool', async t => {
  const cwd = await fixture(t); const tool = createLearnings({cwd}).tool();
  const fact = 'e'.repeat(2000);
  const args = validateToolArguments(tool, {type: 'toolCall', id: 'r', name: tool.name, arguments: {fact}});
  assert.equal(args.fact, fact);
  const result = await tool.execute('r', args, undefined);
  assert.equal(result.isError, undefined, JSON.stringify(result.structuredContent));
});

test('the refusal names the new 2000 limit', async t => {
  const cwd = await fixture(t); const store = createLearnings({cwd});
  const refused = await store.append('f'.repeat(2001));
  assert.equal(refused.ok, false);
  assert.match(refused.reason, /2000/); assert.doesNotMatch(refused.reason, /1024/);
});

test('the other learnings limits are unchanged', async t => {
  const cwd = await fixture(t); const store = createLearnings({cwd});
  for (const fact of ['', null, 'nul\0fact']) assert.equal((await store.append(fact)).ok, false);
  assert.equal((await store.append('seed fact')).ok, true); // creates the private .apex folder the way Apex does
  await writeFile(path.join(cwd, '.apex', 'LEARNINGS.md'), '# Apex learnings\n\n' + Array.from({length: 128}, (_, i) => `- fact ${i}\n`).join(''));
  const full = await store.append('new fact');
  assert.equal(full.ok, false, '128 facts stay the maximum'); assert.match(full.reason, /128/);
  assert.equal((await store.load()).ok, true);
  // 32 KiB stays the file cap: 32 facts of 1000 bytes fit, the 33rd would pass 32768 bytes.
  await writeFile(path.join(cwd, '.apex', 'LEARNINGS.md'), '# Apex learnings\n\n');
  let refusedAt = null;
  for (let i = 0; i < 40 && refusedAt === null; i++) {
    const r = await store.append(`${i} `.padEnd(1000, 'g'));
    if (!r.ok) { refusedAt = i; assert.match(r.reason, /32 KiB/); }
  }
  assert.equal(refusedAt, 32);
  await writeFile(path.join(cwd, '.apex', 'LEARNINGS.md'), 'a'.repeat(40000));
  assert.equal((await store.load()).ok, false);
  const again = await mkdtemp(path.join(process.cwd(), 'tests/.learnings-fixture-')); t.after(() => rm(again, {recursive: true, force: true}));
  const dup = createLearnings({cwd: again});
  assert.equal((await dup.append('same fact')).ok, true);
  assert.equal((await dup.append('same fact')).duplicate, true);
});

import assert from 'node:assert/strict';
import test from 'node:test';
import {mkdtemp, mkdir, rm, writeFile} from 'node:fs/promises';
import path from 'node:path';
import {validateToolArguments} from '@earendil-works/pi-ai';
import {createLearnings} from '../extensions/apex-features/learnings.mjs';

async function fixture(t) { const cwd = await mkdtemp(path.join(process.cwd(), 'tests/.learnings-fixture-')); t.after(() => rm(cwd, {recursive: true, force: true})); return cwd; }
const facts = text => (text.match(/^- /gm) ?? []).length;

test('remember stores facts up to 2000 UTF-8 bytes and refuses longer ones', async t => {
  const cwd = await fixture(t); const store = createLearnings({cwd});
  const long = 'b'.repeat(1990) + ' ok-2000';
  assert.equal(Buffer.byteLength(long), 1998);
  assert.equal((await store.append(long)).ok, true, 'a 1998-byte fact must be stored');
  const exact = 'c'.repeat(2000);
  const stored = await store.append(exact);
  assert.equal(stored.ok, true, stored.reason);
  assert.equal((await store.append('é'.repeat(1000))).ok, true, '2000 bytes of two-byte characters fit');
  assert.equal((await store.append('d'.repeat(2001))).ok, false, '2001 bytes must be refused');
  assert.equal((await store.append('é'.repeat(1001))).ok, false, 'the cap keeps counting UTF-8 bytes (2002 here)');
  const loaded = await store.load();
  assert.equal(loaded.ok, true); assert.equal(facts(loaded.content), 3); assert.ok(loaded.content.includes(exact));
});

test('Pi accepts a 2000-character fact for the remember tool', async t => {
  const cwd = await fixture(t); const tool = createLearnings({cwd}).tool();
  const fact = 'e'.repeat(2000);
  const args = validateToolArguments(tool, {type: 'toolCall', id: 'r', name: tool.name, arguments: {fact}});
  assert.equal(args.fact, fact);
  const result = await tool.execute('r', args, undefined);
  assert.equal(result.isError, undefined, JSON.stringify(result.structuredContent));
});

